      .mobile-menu-btn { display: flex; }
    }

    /* Hero Section */
    .hero {
      min-height: 100vh;
      padding: 8rem 2rem 4rem;
      display: flex;
      flex-direction: column;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .hero-bg {
