      align-items: center;
      gap: 0.5rem;
      color: var(--accent);
      font-weight: 600;
      font-size: 0.9375rem;
      margin-top: 1.5rem;
      transition: gap var(--transition);
    }

    .hero-card-cta:hover { gap: 0.75rem; }

    .hero-card-cta svg { width: 20px; height: 20px; }

    .hero-nav {
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-top: 2rem;
    }

    .hero-dots {
      display: flex;
      gap: 0.5rem;
    }

    .hero-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--border);
      transition: all var(--transition);
      cursor: pointer;
    }

    .hero-dot.active {
