    .hero-arrow svg { width: 20px; height: 20px; }

    @media (max-width: 768px) {
      .hero-slide { grid-template-columns: 1fr; }
      .hero { padding: 6rem 1rem 3rem; }
    }

    /* Team Section */
    .team {
      padding: 6rem 2rem;
      background: var(--bg-secondary);
    }

    .section-header {
      text-align: center;
      margin-bottom: 4rem;
    }

    .section-label {
      color: var(--accent);
