        </div>
      `).join('');
      teamIndex = 0;
      updateTeamCarousel();
    }

    function updateTeamCarousel() {
      const cardWidth = 336; // card width + gap
      teamCarousel.style.transform = `translateX(-${teamIndex * cardWidth}px)`;
      teamPrev.disabled = teamIndex === 0;
      teamNext.disabled = teamIndex >= teamMembers[currentRegion].length - 1;
    }

    teamTabs.addEventListener('click', (e) => {
      if (e.target.classList.contains('team-tab')) {
        document.querySelectorAll('.team-tab').forEach(t => t.classList.remove('active'));
