    function updateWorkCarousel() {
      const cardWidth = 416;
      workCarousel.style.transform = `translateX(-${workIndex * cardWidth}px)`;
      workPrev.disabled = workIndex === 0;
      workNext.disabled = workIndex >= workProjects.length - 1;
